export type AvatarSize = 'sm' | 'md' | 'lg'
export type AvatarShape = 'circle' | 'square'

export interface AvatarProps {
  /** Image URL. Without it, or when it fails to load, the svg, else the initials, show. */
  src?: string
  /** The accessible name: who or what this avatar stands for. Never empty. */
  alt: string
  /**
   * A complete SVG document string generated by the app (for example id-seeded art), drawn as the
   * picture, filling the frame. Never user-supplied markup. Used when there is no `src`, or `src`
   * failed to load; it wins over the initials.
   */
  svg?: string
  /** Shown when there is no image or svg; one or two characters. */
  initials?: string
  /** sm 28, md 40, lg 48 (the controlSm, thumbSm and iconXxl size tokens). Default md. */
  size?: AvatarSize
  /** Default circle. */
  shape?: AvatarShape
}
